import math

def quote(state):
    t, T, best_bid, best_ask, _, _, mid_history, inventory, cash, _, _, memory = state
    mid = (best_bid + best_ask) // 2
    if not mid_history or len(mid_history) < 100:
        mid_history.append(mid)
    else:
        mid_history.pop(0)
        mid_history.append(mid)

    if t == 0:
        memory['last_mid'] = mid
        return {'bid': best_bid - 1, 'bid_size': 5, 'ask': best_ask + 1, 'ask_size': 5}

    target_mid = mid_history[-1]
    delta = target_mid - memory['last_mid']
    memory['last_mid'] = target_mid

    bid = best_bid - 1 if delta < 0 else best_bid
    ask = best_ask + 1 if delta > 0 else best_ask

    if inventory > 0:
        bid = max(bid, best_bid - 2)
    elif inventory < 0:
        ask = min(ask, best_ask + 2)

    return {'bid': bid, 'bid_size': 5, 'ask': ask, 'ask_size': 5}
